const COMMISSION = [
  {id:'k1', t:'ancient', type:'Основной вопрос', q:'Расскажите о причинах и последствиях политической раздробленности Руси.',
    answer:'Раздробленность наступила в XII в. Рост городов и боярского землевладения сделал регионы экономически самостоятельными; борьба князей ослабляла Киев; Любечский съезд (1097) закрепил право держать отчину. Выросли Владимир, Новгород, Галич, Чернигов. Последствия: потеря единства перед нашествием, но развитие региональных культур и вольностей.',
    must:['XII век','ослабление Киева','усиление отдельных княжеств','экономические/политические причины','Любеч 1097'], ref:'c1'},
  {id:'k2', t:'ancient', type:'Вопрос на дату', q:'В каком году произошло Крещение Руси и при каком князе?',
    answer:'988 г., князь Владимир Святой. Принято христианство византийской традиции, крещение населения в Киеве.',
    must:['988','Владимир','византийская традиция'], ref:'d988'},
  {id:'k3', t:'ancient', type:'Вопрос на личность', q:'Кто такой Александр Невский и какова его роль в истории?',
    answer:'Князь новгородский и владимирский (1236–1263). Победил шведов в Невской битве (1240) и Ливонский орден на Чудском озере (1242), защищая западные рубежи. Сохранял мир с Ордой, канонизирован.',
    must:['1240 Нева','1242 Ледовое побоище','компромисс с Ордой','защита запада'], ref:'p_nevsky'},
  {id:'k4', t:'ancient', type:'Причина', q:'Почему монголо-татарское нашествие имело такой разрушительный эффект?',
    answer:'Русь была раздроблена: княжества действовали поодиночке, не было единой армии. Монголы применяли отлаженную тактику осад, а экономика опиралась на города, которые и были разрушены.',
    must:['раздробленность','отсутствие единой армии','тактика осад','разрушение городов'], ref:'c7'},
  {id:'k5', t:'ancient', type:'Сравнение', q:'Сравните Невскую битву и Ледовое побоище.',
    answer:'Обе победы Александра Невского 1240–1242 гг. Нева — против шведов, остановила притязания Швеции; Ледовое побоище — против Ливонского ордена, остановило продвижение с Запада. Обе — защита рубежей под давлением с Востока.',
    must:['1240 и 1242','шведы и Орден','Александр Невский','защита границ'], ref:'p_nevsky'},
  {id:'k6', t:'ancient', type:'Неожиданный вопрос', q:'Почему именно Москва, а не Тверь или Новгород, стала центром объединения?',
    answer:'Москва: выгодное положение на путях, рост населения и земель, гибкая политика князей (ярлыки, союз с Ордой против Твери), поддержка митрополита с 1325 г. Новгород — республика с иным строем, Тверь проиграла соперничество.',
    must:['положение на путях','политика Калиты','поддержка церкви','поражение Твери'], ref:'c6'},
  {id:'k7', t:'moscow', type:'Основной вопрос', q:'Расскажите о причинах и последствиях опричнины.',
    answer:'1564–1567 гг. Причины: подозрения в измене бояр, конфликт с элитой, стремление сломать оппозицию. Сущность: опричный двор, террор, конфискации, карательный поход на Новгород. Последствия: боярство уничтожено, экономика разорена, страна ослабла.',
    must:['1564–1567','террор и конфискации','ослабление хозяйства','усиление самодержавия'], ref:'c12'},
  {id:'k8', t:'moscow', type:'Вопрос на дату', q:'В каком году произошла Куликовская битва и кто её возглавлял?',
    answer:'8 сентября 1380 г. — объединённое войско под командованием Дмитрия Донского против хана Мамая.',
    must:['1380','Дмитрий Донской','Мамай'], ref:'d1380'},
  {id:'k9', t:'moscow', type:'Следствие', q:'Каковы последствия Стояния на Угре 1480 года?',
    answer:'Хан Ахмат отступил, прекратились регулярные выплаты дани — фактический конец зависимости от Орды. Укрепился международный статус Ивана III, завершилось собирание земель.',
    must:['отступление Ахмата','конец дани','усиление Ивана III','собирание земель'], ref:'d1480'},
  {id:'k10', t:'moscow', type:'Основной вопрос', q:'Расскажите о причинах и последствиях Смутного времени.',
    answer:'1598–1613 гг. Причины: пресечение династии, голод 1601–1603, недовольство Годуновым, слабость власти. Ход: самозванцы, интервенция, ополчения. Последствия: избрание Романовых (1613), утрата западных земель, рост национального самосознания.',
    must:['1598–1613','пресечение династии','голод','самозванцы','1613 Романовы'], ref:'c14'},
  {id:'k11', t:'xvii', type:'Вопрос на дату', q:'Когда было принято Соборное уложение и что оно установило?',
    answer:'1649 г. Окончательно закрепостило крестьян: упразднило сроки сыска беглых, ввело бессрочное закрепощение, регулировало посад.',
    must:['1649','бессрочный сыск','закрепощение'], ref:'d1649'},
  {id:'k12', t:'xvii', type:'Причина', q:'Почему вспыхнуло восстание Степана Разина?',
    answer:'Усиление крепостничества, гонения на вольное казачество, действия воевод и приказов, недовольство посадских. Социальный протест против дворян и государства.',
    must:['крепостничество','казачья вольность','воеводы','социальный протест'], ref:'c17'},
  {id:'k13', t:'xvii', type:'Сравнение', q:'Чем реформы Петра отличались от реформ XVII века?',
    answer:'XVII в. — постепенные заимствования (полки иноземного строя, приказы, техника). Пётр I — тотальная принудительная модернизация: губернии, коллегии, Сенат, Синод, Табель, флот, светская культура, новая столица. Масштаб и системность иные.',
    must:['XVII — постепенность','Пётр — тотальность','государственный аппарат','флот и культура'], ref:'e_reforms_petr'},
  {id:'k14', t:'petr', type:'Основной вопрос', q:'Расскажите о реформах Петра I.',
    answer:'Военные (регулярная армия, флот, рекрутчина), государственные (губернии 1708, Сенат 1711, коллегии, Табель 1722), церковные (Синод 1721), сословные, культурные (светские школы, Академия наук 1724). Итог — превращение в империю.',
    must:['армия и флот','губернии и Сенат','Синод','Табель о рангах','светская культура'], ref:'e_reforms_petr'},
  {id:'k15', t:'petr', type:'Вопрос на дату', q:'В каком году подписан Ништадтский мир и что он принёс России?',
    answer:'30 августа 1721 г. Россия получила Прибалтику и выход к Балтийскому морю; провозглашена империей.',
    must:['1721','Балтика','выход к морю','империя'], ref:'d1721'},
  {id:'k16', t:'petr', type:'Причина', q:'Почему вспыхнула крестьянская война Пугачёва?',
    answer:'Усиление крепостничества и податей, рекрутчина, разорение казачества, неприятие реформ. Обещание свободы «по манифесту Петра III» привлекло народ.',
    must:['крепостничество','подати и рекруты','казачество','манифесты'], ref:'c22'},
  {id:'k17', t:'xix1', type:'Основной вопрос', q:'Расскажите о причинах и ходе Отечественной войны 1812 года.',
    answer:'Причина: отказ от континентальной блокады. Ход: вторжение 600-тыс. армии, стратегия отступления и соединения армий, Бородино, оставление Москвы, пожары, изгнание армии зимой.',
    must:['блокада Наполеона','Бородино','Москва и пожары','партизаны','зимнее отступление'], ref:'e_otechestv1812'},
  {id:'k18', t:'xix1', type:'Сравнение', q:'Сравните события 1812 и 1825 годов.',
    answer:'1812 — национально-освободительная война, объединение общества вокруг самодержавия. 1825 — декабристы, протест против самодержавия и крепостничества. 1812 укрепил власть, 1825 показал рост революционных настроений.',
    must:['1812 — освободительная война','1825 — протест','взаимообратный смысл','декабристы'], ref:'e_decembrists'},
  {id:'k19', t:'xix1', type:'Вопрос на личность', q:'Какую роль сыграл Михаил Кутузов в войне 1812 года?',
    answer:'Назначен главнокомандующим после неудач под Смоленском. Стратегия изнурения, генеральное сражение под Москвой, фланговый марш и вытеснение Наполеона. Умер в 1813 г.',
    must:['стратегия изнурения','Бородино','отступление Наполеона','1813'], ref:'p_kutuzov'},
  {id:'k20', t:'xix2', type:'Основной вопрос', q:'Расскажите об отмене крепостного права и содержании реформы.',
    answer:'19 февраля 1861 г. Манифест и «Положения»: личная свобода, надел за выкуп, «временнообязанное» состояние. Недостатки: выкуп, малоземелье. Но это был прорыв: начало капитализма и Великих реформ.',
    must:['19 февраля 1861','личная свобода','надел за выкуп','временнообязанные','начало модернизации'], ref:'e_otmena1861'},
  {id:'k21', t:'xix2', type:'Следствие', q:'Почему отмена крепостного права была необходима?',
    answer:'Крепостничество мешало рынку труда, техническому прогрессу и армии; порождало восстания и отсталость; создавало международный нравственный дискомфорт после Крымской войны.',
    must:['экономика и рынок труда','армия','бунты','Крым как толчок'], ref:'c29'},
  {id:'k22', t:'xix2', type:'Вопрос на дату', q:'Когда была проведена судебная реформа и в чём её суть?',
    answer:'1864 г. Независимый сословный суд, гласность, состязательность, присяжные заседатели, адвокатура.',
    must:['1864','присяжные','адвокатура','гласность'], ref:'d1864b'},
  {id:'k23', t:'xix2', type:'Сравнение', q:'Чем реформы Александра II отличались от политики Александра III?',
    answer:'Александр II — либеральные реформы: отмена крепостного права, земства, суд, армия. Александр III — контрреформы: ограничение земств и печати, «временные правила», усиление полиции, общинный курс.',
    must:['II — реформы','III — контрреформы','земства и суд против полиции','манифест 1881'], ref:'e_control'},
  {id:'k24', t:'turn', type:'Причина', q:'Почему на рубеже XIX–XX веков выросло рабочее движение?',
    answer:'Быстрая индустриализация, концентрация рабочих на заводах, тяжёлый труд, низкие зарплаты, отсутствие прав. Марксистские партии дали организацию и идею.',
    must:['индустриализация','концентрация рабочих','отсутствие прав','партии'], ref:'c33'},
  {id:'k25', t:'turn', type:'Вопрос на личность', q:'Охарактеризуйте роль Петра Столыпина.',
    answer:'Председатель Совета министров (1906–1911). Аграрная реформа: хутора и отрубы, поземельный банк, переселение. Внутри — военно-полевые суды. Убит в 1911 г.',
    must:['1906–1911','реформа деревни','переселение в Сибирь','убийство 1911'], ref:'p_stolypin'},
  {id:'k26', t:'xx1', type:'Основной вопрос', q:'Расскажите о причинах и ходе революции 1905 года.',
    answer:'Причины: поражение в войне, промышленный кризис, безработица, отсутствие политических прав. Ход: 9 января, всеобщая забастовка, Манифест 17 октября, I Дума, подавление, переворот 1907 г.',
    must:['война с Японией','9 января','Манифест 17 октября','I Дума','1907 переворот'], ref:'e_rev1905'},
  {id:'k27', t:'xx1', type:'Следствие', q:'Каковы итоги Первой русской революции?',
    answer:'Появились Дума и партии, временные гражданские свободы, но самодержавие устояло. Опыт легальной борьбы. Итог — реформы 1906–1911 гг. и новый кризис.',
    must:['Дума и партии','временные свободы','самодержавие устояло','Столыпинская реформа'], ref:'e_duma'},
  {id:'k28', t:'xx1', type:'Причина', q:'Почему Первая мировая война стала катализатором революции?',
    answer:'Истощение ресурсов, поражения, голод, беженцы, некомпетентность власти, дискредитация монархии. Война обнажила все противоречия империи.',
    must:['истощение','поражения и голод','дискредитация двора','отсталость управления'], ref:'e_ww1'},
  {id:'k29', t:'civ', type:'Основной вопрос', q:'Расскажите о Февральской революции 1917 года.',
    answer:'23 февраля — забастовки и демонстрации в Петрограде, переход гарнизона на сторону восставших, 2 марта отречение Николая II. Временное правительство и Петросовет — двоевластие. Монархия пала.',
    must:['23 февраля','переход солдат','2 марта отречение','двоевластие'], ref:'e_fevral1917'},
  {id:'k30', t:'civ', type:'Следствие', q:'Что произошло после Октябрьской революции 1917 года?',
    answer:'II съезд Советов провозгласил власть Советов, создано правительство во главе с Лениным, приняты декреты о мире и земле, разогнано Учредительное собрание, подписан Брестский мир.',
    must:['II съезд','декреты','Учредительное собрание','Брестский мир'], ref:'e_oktyabr1917'},
  {id:'k31', t:'civ', type:'Сравнение', q:'Сравните политику «военного коммунизма» и НЭП.',
    answer:'«Военный коммунизм»: продразвёрстка, национализация, запрет торговли — мобилизация ресурсов на войну, но кризис. НЭП: продналог, свободная торговля, частная торговля — восстановление через материальные стимулы.',
    must:['развёрстка против продналога','национализация против рынка','кризис 1920–1921','восстановление'], ref:'e_nep'},
  {id:'k32', t:'civ', type:'Неожиданный вопрос', q:'Почему большевики победили в Гражданской войне?',
    answer:'Единое командование и централизация, контроль над центром, транспортом и промышленностью, мобилизация, разобщённость противников, отсутствие единой программы у белых.',
    must:['центр и ресурсы','единство против разобщённости','ошибки белых','мобилизация'], ref:'c39'},
  {id:'k33', t:'civ', type:'Вопрос на дату', q:'Когда было образовано СССР и из каких республик?',
    answer:'30 декабря 1922 г. Из РСФСР, УССР, БССР и ЗСФСР в форме федерации.',
    must:['30 декабря 1922','четыре республики','федерация'], ref:'d1922'},
  {id:'k34', t:'xix2', type:'Вопрос на личность', q:'Охарактеризуйте Александра III и его внутреннюю политику.',
    answer:'Правил 1881–1894. Манифест о незыблемости самодержавия, ограничение земств и печати, крестьянский банк, «временные правила». Консерватизм, русификация, поддержка общины.',
    must:['1881–1894','манифест','контрреформы','русификация'], ref:'p_alexander3'},
  {id:'k35', t:'petr', type:'Сравнение', q:'Сравните Северную войну и Крымскую войну.',
    answer:'Северная (1700–1721) — успешная за выход к Балтике, сделала Россию империей. Крымская (1853–1856) — поражение из-за отсталости, привело к реформам. Обе — про внешнюю политику, но противоположный итог.',
    must:['1700–1721 против 1853–1856','победа против поражения','Балтика против Чёрного моря','реформы как итог Крыма'], ref:'e_krymskaya'},
  {id:'k36', t:'ancient', type:'Следствие', q:'Каковы последствия крещения Руси для культуры и политики?',
    answer:'Единая вера укрепила государство, появились письменность и летописание, храмы и школы, византийское право и искусство, связи с Европой. Политически — союз с Византией и претензии на её наследие.',
    must:['единство','письменность и школы','храмы','византийское наследие'], ref:'e_kreshchenie'}
];

